import os
import time
import base64
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import ClientError


class CognitoTokenRefresher:
    def __init__(
        self,
        user_pool_client_id: str,
        region_name: Optional[str] = None,
        client_secret: Optional[str] = None,
    ):
        self.user_pool_client_id = user_pool_client_id
        self.client_secret = client_secret or os.getenv("COGNITO_CLIENT_SECRET")
        self.client = boto3.client(
            "cognito-idp",
            region_name=region_name or os.getenv("AWS_REGION"),
        )

    def _secret_hash(self, username: str) -> str:
        if not self.client_secret:
            return ""
        import hmac
        import hashlib

        message = (username + self.user_pool_client_id).encode("utf-8")
        key = self.client_secret.encode("utf-8")
        digest = hmac.new(key, message, hashlib.sha256).digest()
        return base64.b64encode(digest).decode("utf-8")

    def refresh(
        self,
        refresh_token: str,
        username: Optional[str] = None,
    ) -> Dict[str, Any]:
        auth_parameters = {
            "REFRESH_TOKEN": refresh_token,
        }
        if username:
            auth_parameters["USERNAME"] = username
            secret_hash = self._secret_hash(username)
            if secret_hash:
                auth_parameters["SECRET_HASH"] = secret_hash

        try:
            response = self.client.initiate_auth(
                ClientId=self.user_pool_client_id,
                AuthFlow="REFRESH_TOKEN_AUTH",
                AuthParameters=auth_parameters,
            )
        except ClientError as e:
            raise RuntimeError(f"Failed to refresh Cognito session/token: {e}") from e

        result = response.get("AuthenticationResult", {})
        return {
            "access_token": result.get("AccessToken"),
            "id_token": result.get("IdToken"),
            "expires_in": result.get("ExpiresIn"),
            "token_type": result.get("TokenType"),
            "refresh_token": result.get("RefreshToken", refresh_token),
            "received_at": int(time.time()),
        }


def refresh_expired_session_or_access_token(
    refresh_token: str,
    user_pool_client_id: Optional[str] = None,
    username: Optional[str] = None,
    region_name: Optional[str] = None,
) -> Dict[str, Any]:
    client_id = user_pool_client_id or os.getenv("COGNITO_USER_POOL_CLIENT_ID")
    if not client_id:
        raise ValueError("Missing Cognito app client ID. Set COGNITO_USER_POOL_CLIENT_ID.")

    refresher = CognitoTokenRefresher(
        user_pool_client_id=client_id,
        region_name=region_name,
        client_secret=os.getenv("COGNITO_CLIENT_SECRET"),
    )
    return refresher.refresh(refresh_token=refresh_token, username=username)
